mapper.select:
SELECT m.META_ID ,m.DATA_ID ,m.USER_ID ,m.CREATED_DATE ,m.INFO ,m.LABEL ,m.LABEL_TYPE FROM META m WHERE 1=1
AND m.DATA_ID = #{data_id}
AND m.USER_ID = #{user_id}
AND m.DATA_ID IN (${data_ids})
AND m.LABEL = #{LABEL}

mapper.update:
INSERT INTO META (
	META_ID
	,DATA_ID
	,USER_ID
	,CREATED_DATE
	,INFO
	,LABEL
	,LABEL_TYPE
) VALUES (
	#{meta_id}
	,#{data_id}
	,#{user_id}
	,now()
	,#{info}
	,#{label}
	,#{label_type}
) ON DUPLICATE KEY UPDATE 
	LABEL = #{label},
	CREATED_DATE = now(),
	INFO = #{info}

mapper.delete:
	    DELETE FROM META
	    WHERE 1=1 
    	   	AND META_ID = #{meta_id}
